/// <summary>
/// AVA FormControl AVASQClerk
/// </summary>
[ExtensionOf(formControlStr(SalesTableListPage, AVASQClerk))]
final class AVASalesTableListPageFrmCtr_AVASQClerk_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret = next modified();

    FormDataSource avaSalesTable_ds = this.formRun().dataSource(tableStr(SalesTable));
    AVASQClerk sqClerk = this.value();

    if (sqClerk)
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, AVASQClerk)).value(queryValue(sqClerk));
    }
    else
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, AVASQClerk)).value(SysQueryRangeUtil::valueUnlimited());
    }

    avaSalesTable_ds.executeQuery();

    return ret;
}
